-- HIT - Bounce 직무 트랙 역량 해설 — 비마케팅 17트랙 × 6역량 × 3단계 = 306개 (2026-10-12 적용)
-- 단계·선택 규칙은 sql/hit-b-track-modules-2026-10.sql 과 같다 (TRK-{sub_domain}-{H|M|L}, H 75+ · M 50~74 · L 50 미만)
-- 이 파일로 22개 트랙 전부 전용 해설. 미디어/방송 프로그램 기획 = program_planning (sql/hit-b-media-program-planning-2026-10.sql)
-- 재실행 가능. 롤백: 이 파일의 id만 DELETE (마케팅 TRK-*는 그대로 둘 것)

INSERT INTO public.hit_report_modules (id, category, title, content) VALUES
-- it_dev
('TRK-coding-H', 'track_competency', '코딩 — 강점으로 보여 주기', '요구사항을 읽기 좋은 코드로 구현하고 오류 원인을 찾아내는 힘이 강점입니다. 직접 만든 프로젝트를 깃허브에 올리고, 디버깅으로 문제를 해결한 과정을 README에 적어 두세요.'),
('TRK-coding-M', 'track_competency', '코딩 — 다음에 더할 것', '기능을 구현하는 기본기는 갖추고 있습니다. 같은 문제를 배열과 해시맵 두 방식으로 풀어 비교하고, 친구나 스터디원에게 코드 리뷰를 받아 보세요.'),
('TRK-coding-L', 'track_competency', '코딩 — 첫걸음', '이번 주에 무료 코딩 문제 사이트에서 쉬운 문제 세 개를 풀고, 막혔던 에러 메시지를 메모해 보세요. 에러를 읽는 습관이 실력의 시작입니다.'),
('TRK-architecture-H', 'track_competency', '설계·아키텍처 — 강점으로 보여 주기', '구현 전에 구조를 먼저 그리는 습관이 강점입니다. 프로젝트의 API 설계와 테이블 구조를 그림 한 장으로 정리해 포트폴리오에 넣고, 왜 그렇게 설계했는지 말해 보세요.'),
('TRK-architecture-M', 'track_competency', '설계·아키텍처 — 다음에 더할 것', '설계를 고민하는 감각은 있습니다. 만든 프로젝트의 테이블 구조를 다시 그려 보며 사용자가 늘면 어디가 느려질지 적어 보세요.'),
('TRK-architecture-L', 'track_competency', '설계·아키텍처 — 첫걸음', '도서 대여나 할 일 목록 같은 작은 앱을 정해 필요한 테이블과 API 주소를 종이에 먼저 적어 보세요. 코드를 짜기 전에 구조를 그리는 연습이 됩니다.'),
('TRK-testing-H', 'track_competency', '테스트 — 강점으로 보여 주기', '품질을 검증하고 예외 상황까지 챙기는 태도가 강점입니다. 프로젝트에 단위 테스트와 발견한 버그의 재현 과정을 함께 남겨 두면 꼼꼼함의 증거가 됩니다.'),
('TRK-testing-M', 'track_competency', '테스트 — 다음에 더할 것', '테스트의 필요성은 이해하고 있습니다. 내 프로젝트의 핵심 함수 하나에 정상·예외 입력 테스트를 작성하고, 린트 도구도 한 번 돌려 보세요.'),
('TRK-testing-L', 'track_competency', '테스트 — 첫걸음', '내가 짠 함수 하나를 골라 이상한 값(빈 값, 음수, 아주 큰 수)을 넣어 보고 어떻게 되는지 적어 보세요. 테스트는 이런 확인에서 시작합니다.'),
('TRK-dev_tools-H', 'track_competency', '개발 도구 — 강점으로 보여 주기', '버전 관리와 배포 환경을 직접 다루는 힘이 강점입니다. 깃 커밋 기록을 깔끔하게 남기고, 배포나 컨테이너 설정 경험을 프로젝트 설명에 구체적으로 적어 두세요.'),
('TRK-dev_tools-M', 'track_competency', '개발 도구 — 다음에 더할 것', '깃과 기본 개발 환경은 다룰 수 있습니다. 무료 클라우드 서비스에 작은 프로젝트를 올리고 자동 배포를 한 번 설정해 보세요.'),
('TRK-dev_tools-L', 'track_competency', '개발 도구 — 첫걸음', '이번 주에 개인 저장소를 만들어 브랜치를 하나 따서 수정하고 합치는 과정을 해 보세요. 이 흐름이 협업 개발의 기본입니다.'),
('TRK-dev_collab-H', 'track_competency', '개발 협업 — 강점으로 보여 주기', '기획을 기술로 풀어 말하고 문서로 남기는 협업 감각이 강점입니다. 팀 프로젝트에서 맡은 소통·문서화 역할과 기여한 오픈소스 사례를 이력서에 적어 보세요.'),
('TRK-dev_collab-M', 'track_competency', '개발 협업 — 다음에 더할 것', '함께 만드는 경험이 쌓이고 있습니다. 프로젝트마다 설치와 실행 방법을 담은 README를 쓰고, 비전공자 친구에게 기능을 설명해 보세요.'),
('TRK-dev_collab-L', 'track_competency', '개발 협업 — 첫걸음', '관심 있는 오픈소스 저장소의 README와 이슈 목록을 읽어 보세요. 다른 사람이 협업하는 방식을 보는 것만으로도 첫걸음이 됩니다.'),
('TRK-dev_growth-H', 'track_competency', '기술 성장 — 강점으로 보여 주기', '새 기술을 독학해 프로젝트에 적용하는 학습력이 강점입니다. 무엇을 어떻게 익혔고 코드를 어떻게 개선했는지 블로그나 프로젝트 기록으로 남겨 보여 주세요.'),
('TRK-dev_growth-M', 'track_competency', '기술 성장 — 다음에 더할 것', '꾸준히 배우려는 자세가 있습니다. 새로 배운 기술 하나를 작은 결과물로 만들고, 예전 코드를 리팩토링한 변화를 기록으로 남겨 보세요.'),
('TRK-dev_growth-L', 'track_competency', '기술 성장 — 첫걸음', '이번 주에 관심 있는 개발 강의나 기술 블로그 글 하나를 끝까지 따라 해 보세요. 생성형 AI 도구에 코드 설명을 부탁해 보는 것도 좋습니다.'),
-- it_planning
('TRK-service_planning-H', 'track_competency', '서비스 기획 — 강점으로 보여 주기', '사용자 문제를 정의하고 기능 우선순위를 매기는 힘이 강점입니다. 문제 정의, 사용자 시나리오, 경쟁 서비스 비교가 담긴 기획서를 포트폴리오로 만들어 두세요.'),
('TRK-service_planning-M', 'track_competency', '서비스 기획 — 다음에 더할 것', '서비스 아이디어를 구체화하는 기본기가 있습니다. 쓰는 앱 하나의 기능을 핵심과 부가로 나눠 보고, 개발자가 읽을 수 있는 기능 명세서로 써 보세요.'),
('TRK-service_planning-L', 'track_competency', '서비스 기획 — 첫걸음', '자주 쓰는 앱에서 불편했던 점을 하나 골라 "누가, 언제, 왜 불편한가"를 세 줄로 적어 보세요. 문제를 정의하는 연습이 기획의 시작입니다.'),
('TRK-product_mgmt-H', 'track_competency', '프로덕트 관리 — 강점으로 보여 주기', '로드맵과 지표를 바탕으로 제품을 이끄는 감각이 강점입니다. MVP 범위를 정한 이유와 사용자 피드백으로 바꾼 기능 사례를 숫자와 함께 정리해 두세요.'),
('TRK-product_mgmt-M', 'track_competency', '프로덕트 관리 — 다음에 더할 것', '제품 관리의 흐름은 이해하고 있습니다. 동아리나 개인 프로젝트에 분기별 로드맵과 핵심 지표 두세 개를 직접 정해 운영해 보세요.'),
('TRK-product_mgmt-L', 'track_competency', '프로덕트 관리 — 첫걸음', '좋아하는 서비스의 최근 업데이트 내용을 읽고 "왜 이 기능을 먼저 만들었을까"를 추측해 적어 보세요. 우선순위를 읽는 눈이 길러집니다.'),
('TRK-project_mgmt-H', 'track_competency', '프로젝트 관리 — 강점으로 보여 주기', '일정을 관리하고 이해관계자 의견을 조율하는 힘이 강점입니다. 협업 도구로 운영한 일정표와 위험을 미리 막은 사례를 팀 프로젝트 설명에 구체적으로 적어 보세요.'),
('TRK-project_mgmt-M', 'track_competency', '프로젝트 관리 — 다음에 더할 것', '일정과 협업 도구를 다뤄 본 경험이 있습니다. 다음 프로젝트에서는 시작 전에 위험 요소 세 가지와 대응책을 적고, 스프린트 방식으로 회고도 해 보세요.'),
('TRK-project_mgmt-L', 'track_competency', '프로젝트 관리 — 첫걸음', '무료 협업 도구에서 칸반 보드를 만들어 이번 주 할 일을 "할 일·진행 중·완료"로 옮겨 보세요. 일을 눈에 보이게 만드는 것이 첫걸음입니다.'),
('TRK-ux_understanding-H', 'track_competency', 'UX 이해 — 강점으로 보여 주기', '사용자의 불편을 찾아 화면으로 개선안을 내는 힘이 강점입니다. 인터뷰 결과, 와이어프레임, 사용성 테스트에서 얻은 개선점을 한 흐름으로 묶어 보여 주세요.'),
('TRK-ux_understanding-M', 'track_competency', 'UX 이해 — 다음에 더할 것', '사용자 관점으로 보는 감각이 있습니다. 주변 사람 세 명에게 앱을 써 보게 하고 막힌 지점을 관찰해, 무료 디자인 도구로 개선 화면을 그려 보세요.'),
('TRK-ux_understanding-L', 'track_competency', 'UX 이해 — 첫걸음', '이번 주에 쓰는 앱 하나의 화면 흐름을 종이에 손으로 그려 보세요. 어디서 헷갈렸는지 표시하면 사용자 경험을 보는 연습이 됩니다.'),
('TRK-data_literacy-H', 'track_competency', '데이터 리터러시 — 강점으로 보여 주기', '지표를 해석해 판단의 근거로 쓰는 힘이 강점입니다. 분석 도구나 스프레드시트로 지표를 살펴 개선안을 낸 사례를 "데이터 → 판단 → 결과" 순서로 정리해 두세요.'),
('TRK-data_literacy-M', 'track_competency', '데이터 리터러시 — 다음에 더할 것', '지표의 뜻을 이해하고 있습니다. 개인 블로그나 프로젝트 페이지에 무료 분석 도구를 붙여 보고, 간단한 A/B 테스트 가설을 하나 세워 보세요.'),
('TRK-data_literacy-L', 'track_competency', '데이터 리터러시 — 첫걸음', '전환율과 이탈률의 뜻을 찾아 정리하고, 공개된 서비스 지표 예시 하나를 스프레드시트에 옮겨 계산해 보세요.'),
('TRK-tech_literacy-H', 'track_competency', '기술 이해 — 강점으로 보여 주기', '개발 구조를 이해하고 개발자와 용어로 소통하는 힘이 강점입니다. 기술적 제약을 기획에 반영해 일정을 줄인 사례를 면접에서 구체적으로 말해 보세요.'),
('TRK-tech_literacy-M', 'track_competency', '기술 이해 — 다음에 더할 것', '기본 개념은 이해하고 있습니다. 공개 API 문서를 읽고 직접 요청을 보내 응답을 확인해 보면 개발자와의 대화가 훨씬 수월해집니다.'),
('TRK-tech_literacy-L', 'track_competency', '기술 이해 — 첫걸음', '앱 하나를 골라 화면에 보이는 부분(프론트엔드)과 서버가 하는 일(백엔드)을 나눠 적어 보세요. 구조를 보는 눈이 생깁니다.'),
-- it_data
('TRK-data_processing-H', 'track_competency', '데이터 처리 — 강점으로 보여 주기', '쿼리와 코드로 데이터를 정리하는 힘이 강점입니다. 결측값과 중복을 처리한 전후를 비교하고, 쓴 SQL과 파이썬 코드를 분석 프로젝트에 함께 공개해 보세요.'),
('TRK-data_processing-M', 'track_competency', '데이터 처리 — 다음에 더할 것', '조회와 정제의 기본기는 있습니다. 공공데이터 두 개를 JOIN으로 합쳐 집계해 보고, 이상치를 어떻게 처리했는지 근거와 함께 기록해 보세요.'),
('TRK-data_processing-L', 'track_competency', '데이터 처리 — 첫걸음', '이번 주에 무료 SQL 실습 사이트에서 SELECT와 GROUP BY 문제를 다섯 개 풀어 보세요. 작은 데이터로 집계하는 경험이 출발점입니다.'),
('TRK-statistics-H', 'track_competency', '통계 — 강점으로 보여 주기', '평균 너머의 분포와 검정, 인과 해석까지 판단하는 힘이 강점입니다. 가설 검정을 직접 해 본 분석 사례에 표본 크기와 해석의 한계를 함께 적어 보여 주세요.'),
('TRK-statistics-M', 'track_competency', '통계 — 다음에 더할 것', '기초 개념은 갖추고 있습니다. 공개 데이터로 두 집단의 평균 차이를 t-검정해 보고, 상관이 인과가 아닌 이유를 한 단락으로 설명해 보세요.'),
('TRK-statistics-L', 'track_competency', '통계 — 첫걸음', '좋아하는 주제의 숫자 열 개를 모아 평균과 중앙값을 각각 구해 보세요. 두 값이 다르면 왜 그런지 적어 보는 것이 첫걸음입니다.'),
('TRK-visualization-H', 'track_competency', '시각화 — 강점으로 보여 주기', '목적에 맞는 차트를 고르고 오해 없이 전달하는 힘이 강점입니다. 직접 만든 대시보드 화면과 "누가 무엇을 보려고 만들었는지"를 포트폴리오에 함께 담아 보세요.'),
('TRK-visualization-M', 'track_competency', '시각화 — 다음에 더할 것', '차트를 고르는 기본기가 있습니다. 무료 BI 도구로 핵심 지표 세 개짜리 대시보드를 만들고, 비전공자에게 보여 주며 이해되는지 확인해 보세요.'),
('TRK-visualization-L', 'track_competency', '시각화 — 첫걸음', '뉴스에서 본 그래프 하나를 골라 축이 잘렸는지, 비율이 왜곡됐는지 살펴보세요. 같은 데이터를 막대와 선 두 가지로 그려 보는 것도 좋습니다.'),
('TRK-ml_basics-H', 'track_competency', '머신러닝 기초 — 강점으로 보여 주기', '모델의 원리와 성능 지표를 이해하고 쓸 수 있는 힘이 강점입니다. 모델을 만들며 과적합을 어떻게 줄였는지, 지표를 어떻게 골랐는지 노트북 파일로 공개해 보세요.'),
('TRK-ml_basics-M', 'track_competency', '머신러닝 기초 — 다음에 더할 것', '기본 개념은 이해하고 있습니다. 공개 데이터로 분류 모델 하나를 만들고 정확도와 재현율을 함께 비교하며 결과를 해석하는 연습을 더해 보세요.'),
('TRK-ml_basics-L', 'track_competency', '머신러닝 기초 — 첫걸음', '지도학습과 비지도학습의 차이를 일상 예시와 함께 적어 보세요. 무료 입문 강의의 첫 실습을 따라 해 보는 것도 좋은 시작입니다.'),
('TRK-data_eng-H', 'track_competency', '데이터 엔지니어링 — 강점으로 보여 주기', '데이터를 모으고 흐름을 만드는 구조를 이해하는 힘이 강점입니다. API로 수집해 저장하고 정합성을 점검하는 흐름을 그림과 코드로 정리해 보여 주세요.'),
('TRK-data_eng-M', 'track_competency', '데이터 엔지니어링 — 다음에 더할 것', '파이프라인의 개념은 알고 있습니다. 공개 API에서 데이터를 매일 받아 DB에 쌓는 작은 흐름을 만들고, 값이 비었는지 확인하는 점검을 넣어 보세요.'),
('TRK-data_eng-L', 'track_competency', '데이터 엔지니어링 — 첫걸음', '관계형 DB와 NoSQL의 차이를 표로 정리해 보세요. 공공데이터 포털의 API 하나를 호출해 응답을 눈으로 확인하는 것이 첫걸음입니다.'),
('TRK-biz_insight-H', 'track_competency', '비즈니스 인사이트 — 강점으로 보여 주기', '분석을 사업 결정으로 잇고 쉽게 전하는 힘이 강점입니다. 분석 목적, 발견한 패턴, 제안한 행동을 한 장짜리 보고서로 만들어 발표한 경험을 보여 주세요.'),
('TRK-biz_insight-M', 'track_competency', '비즈니스 인사이트 — 다음에 더할 것', '분석을 의사결정에 잇는 감각이 있습니다. 분석 전에 "이 결과로 누가 무엇을 결정하나"를 먼저 적고, 결과를 세 문장 이야기로 요약해 보세요.'),
('TRK-biz_insight-L', 'track_competency', '비즈니스 인사이트 — 첫걸음', '공개된 매출이나 이용자 통계 하나를 보고 "이 숫자로 무엇을 결정할 수 있나"를 세 줄로 적어 보세요. 숫자와 결정을 잇는 연습이 됩니다.'),
-- ux_design
('TRK-user_research-H', 'track_competency', '사용자 리서치 — 강점으로 보여 주기', '인터뷰와 사용성 테스트로 문제를 찾아내는 힘이 강점입니다. 퍼소나와 여정 지도가 실제 디자인 결정으로 이어진 과정을 사례 하나로 묶어 보여 주세요.'),
('TRK-user_research-M', 'track_competency', '사용자 리서치 — 다음에 더할 것', '리서치의 기본기를 갖췄습니다. 인터뷰 질문지를 직접 설계해 세 명에게 진행하고, 정량 자료인 클릭 데이터와 함께 해석하는 연습을 더해 보세요.'),
('TRK-user_research-L', 'track_competency', '사용자 리서치 — 첫걸음', '주변 한 사람에게 자주 쓰는 앱 이야기를 10분 동안 물어보고 불편했던 순간을 적어 보세요. 인터뷰의 출발이 됩니다.'),
('TRK-interaction_design-H', 'track_competency', '인터랙션 디자인 — 강점으로 보여 주기', '화면 흐름과 정보 구조를 설계하고 프로토타입으로 검증하는 힘이 강점입니다. 흐름도, 와이어프레임, 테스트 결과를 한 프로젝트 안에서 이어 보여 주세요.'),
('TRK-interaction_design-M', 'track_competency', '인터랙션 디자인 — 다음에 더할 것', '흐름을 그리는 기본기는 있습니다. 앱 하나의 정보 구조를 다시 짜 보고, 탭·모달 같은 패턴을 바꿨을 때 사용 흐름이 어떻게 달라지는지 비교해 보세요.'),
('TRK-interaction_design-L', 'track_competency', '인터랙션 디자인 — 첫걸음', '종이에 앱 화면 세 장을 손으로 그려 연결해 보세요. 흐름도와 와이어프레임의 가장 쉬운 시작입니다.'),
('TRK-visual_design-H', 'track_competency', '비주얼 디자인 — 강점으로 보여 주기', '색상, 글자, 배치를 일관되게 다루고 접근성까지 챙기는 힘이 강점입니다. 디자인 시스템 일부와 반응형 화면을 함께 보여 주면 완성도가 잘 전달됩니다.'),
('TRK-visual_design-M', 'track_competency', '비주얼 디자인 — 다음에 더할 것', '시각 원칙의 기본기는 있습니다. 같은 화면을 모바일과 데스크톱에 맞게 다시 설계하고, 글자 대비가 충분한지 무료 검사 도구로 확인해 보세요.'),
('TRK-visual_design-L', 'track_competency', '비주얼 디자인 — 첫걸음', '마음에 드는 앱 화면 하나를 골라 쓰인 색상 수와 글자 크기 단계를 세어 적어 보세요. 시각 원칙이 눈에 들어오기 시작합니다.'),
('TRK-design_tools-H', 'track_competency', '디자인 도구 — 강점으로 보여 주기', '컴포넌트와 프로토타입을 능숙하게 다루고 구현 가능성까지 보는 힘이 강점입니다. 직접 만든 파일 링크와 개발 전달 경험을 포트폴리오에 함께 담아 보세요.'),
('TRK-design_tools-M', 'track_competency', '디자인 도구 — 다음에 더할 것', '도구의 기본 기능은 다룰 수 있습니다. 컴포넌트와 오토레이아웃으로 버튼·카드 세트를 만들고, 기본 HTML/CSS도 조금 익혀 구현을 상상해 보세요.'),
('TRK-design_tools-L', 'track_competency', '디자인 도구 — 첫걸음', '무료 디자인 도구 계정을 만들어 앱 로그인 화면 하나를 따라 그려 보세요. 사각형과 글자만으로도 충분한 첫 연습입니다.'),
('TRK-design_collab-H', 'track_competency', '디자인 협업 — 강점으로 보여 주기', '디자인 의도를 전하고 근거로 설득하며 여러 요구를 조율하는 힘이 강점입니다. 의견이 갈렸을 때 리서치로 결론을 낸 사례를 포트폴리오에 짧게 적어 보세요.'),
('TRK-design_collab-M', 'track_competency', '디자인 협업 — 다음에 더할 것', '함께 일하는 감각이 있습니다. 디자인을 넘길 때 간격·상태·예외 화면을 정리한 설명을 붙이고, 결정의 근거를 데이터나 인터뷰로 한 줄씩 덧붙여 보세요.'),
('TRK-design_collab-L', 'track_competency', '디자인 협업 — 첫걸음', '내 디자인을 친구에게 보여 주고 피드백을 세 가지 받아 보세요. 반박하지 않고 그대로 적는 연습이 협업의 첫걸음입니다.'),
('TRK-design_growth-H', 'track_competency', '디자인 성장 — 강점으로 보여 주기', '트렌드를 관찰하고 서비스 경험을 분석하며 자기 원칙을 세우는 힘이 강점입니다. 분석 노트와 나만의 디자인 원칙을 글로 정리해 공개해 보세요.'),
('TRK-design_growth-M', 'track_competency', '디자인 성장 — 다음에 더할 것', '꾸준히 배우는 태도가 있습니다. 매주 서비스 하나의 UX를 분석해 배울 점을 세 줄로 기록하고, AI 디자인 도구를 아이디어 탐색에 써 보세요.'),
('TRK-design_growth-L', 'track_competency', '디자인 성장 — 첫걸음', '자주 쓰는 앱의 화면을 캡처해 마음에 든 점 하나와 아쉬운 점 하나를 적어 보세요. 이런 기록이 쌓이면 나만의 기준이 됩니다.'),
-- startup_general
('TRK-business_model-H', 'track_competency', '비즈니스 모델 — 강점으로 보여 주기', '고객 문제를 찾아 돈 버는 구조로 풀어내는 힘이 강점입니다. 비즈니스 모델 캔버스와 고객 인터뷰로 가설을 검증한 기록을 한 장으로 묶어 보여 주세요.'),
('TRK-business_model-M', 'track_competency', '비즈니스 모델 — 다음에 더할 것', '모델을 그려 본 경험이 있습니다. 구독·광고·수수료 중 두 가지 수익 모델을 같은 아이디어에 적용해 비교하고, 시장 규모를 직접 추정해 보세요.'),
('TRK-business_model-L', 'track_competency', '비즈니스 모델 — 첫걸음', '좋아하는 서비스가 누구에게 무엇을 주고 어떻게 돈을 버는지 한 장의 캔버스에 적어 보세요. 구조를 읽는 연습이 됩니다.'),
('TRK-startup_execution-H', 'track_competency', '실행력 — 강점으로 보여 주기', '제한된 자원에서 빠르게 만들고 시장에 내놓는 힘이 강점입니다. 작은 제품을 내놓은 과정, 방향을 바꾼 이유, 얻은 교훈을 시간순으로 정리해 두세요.'),
('TRK-startup_execution-M', 'track_competency', '실행력 — 다음에 더할 것', '실행하려는 의지와 경험이 있습니다. 일주일 안에 만들 수 있는 최소 버전을 정해 지인 열 명에게 써 보게 하고, 반응으로 다음 우선순위를 정해 보세요.'),
('TRK-startup_execution-L', 'track_competency', '실행력 — 첫걸음', '아이디어 하나를 골라 이번 주말까지 만들 수 있는 가장 작은 형태를 정하세요. 무료 폼이나 노코드 도구로 페이지를 만드는 것도 좋습니다.'),
('TRK-growth-H', 'track_competency', '그로스 — 강점으로 보여 주기', '초기 사용자를 모으고 유지 전략까지 고민하는 힘이 강점입니다. 어떤 채널에서 몇 명이 들어와 얼마나 남았는지 숫자로 정리하면 설득력이 큽니다.'),
('TRK-growth-M', 'track_competency', '그로스 — 다음에 더할 것', '성장 개념은 이해하고 있습니다. 작은 프로젝트에 가입, 재방문 같은 단계별 숫자를 세어 보고, 가장 많이 이탈하는 구간을 하나 찾아 보세요.'),
('TRK-growth-L', 'track_competency', '그로스 — 첫걸음', '관심 있는 서비스가 사용자를 어떻게 모으는지 블로그나 커뮤니티에서 세 가지 찾아 적어 보세요. 채널을 보는 눈이 생깁니다.'),
('TRK-funding-H', 'track_competency', '투자 유치 — 강점으로 보여 주기', '투자 단계와 재무 용어를 이해하고 제안서로 정리하는 힘이 강점입니다. 직접 쓴 피치덱이나 정부 지원 사업 지원서를 근거 숫자와 함께 보여 주세요.'),
('TRK-funding-M', 'track_competency', '투자 유치 — 다음에 더할 것', '투자 구조의 기본은 알고 있습니다. 아이디어 하나로 열 장짜리 피치덱을 써 보고, 번 레이트와 손익분기점을 스프레드시트로 직접 계산해 보세요.'),
('TRK-funding-L', 'track_competency', '투자 유치 — 첫걸음', '공개된 스타트업 투자 기사 하나를 읽고 투자 단계와 금액, 지분 변화를 정리해 보세요. 공개된 창업 지원 사업 공고도 한번 읽어 볼 만합니다.'),
('TRK-team_building-H', 'track_competency', '팀 빌딩 — 강점으로 보여 주기', '사람을 모으고 비전을 전하며 갈등을 조율하는 힘이 강점입니다. 팀원을 합류시킨 계기, 역할 배분 기준, 갈등을 푼 사례를 구체적으로 이야기해 보세요.'),
('TRK-team_building-M', 'track_competency', '팀 빌딩 — 다음에 더할 것', '함께하는 사람을 이끈 경험이 있습니다. 동아리나 팀 프로젝트에서 팀원 강점표를 만들어 역할을 다시 나누고, 팀의 일하는 규칙을 한 장으로 적어 보세요.'),
('TRK-team_building-L', 'track_competency', '팀 빌딩 — 첫걸음', '내가 속한 모임에서 각자 잘하는 것을 한 줄씩 적어 보세요. 사람의 강점을 먼저 보는 연습이 팀 빌딩의 시작입니다.'),
('TRK-legal_admin-H', 'track_competency', '법무·행정 — 강점으로 보여 주기', '창업에 필요한 설립, 계약, 지식재산, 세무 기초를 아는 점이 강점입니다. 개인정보와 전자상거래 이슈를 점검한 체크리스트를 만들어 두면 신뢰를 줍니다.'),
('TRK-legal_admin-M', 'track_competency', '법무·행정 — 다음에 더할 것', '기본 개념은 알고 있습니다. 공개된 표준 근로계약서를 읽어 핵심 조항에 표시하고, 내 아이디어에 필요한 상표 검색을 무료 검색 서비스로 해 보세요.'),
('TRK-legal_admin-L', 'track_competency', '법무·행정 — 첫걸음', '법인 설립에 필요한 서류와 절차를 정부 안내 페이지에서 찾아 목록으로 적어 보세요. 막연한 행정이 눈에 보이는 일이 됩니다.'),
-- sales_biz
('TRK-needs_analysis-H', 'track_competency', '니즈 파악 — 강점으로 보여 주기', '질문으로 고객의 진짜 문제를 찾고 유형별로 접근을 바꾸는 힘이 강점입니다. 고객이 말한 요구 뒤의 진짜 문제를 찾아낸 사례를 질문과 함께 정리해 두세요.'),
('TRK-needs_analysis-M', 'track_competency', '니즈 파악 — 다음에 더할 것', '고객 이야기를 듣는 감각이 있습니다. 가상의 고객 세 유형을 정해 유형별 질문 다섯 개씩을 만들고, 타깃 고객군을 나누는 기준을 적어 보세요.'),
('TRK-needs_analysis-L', 'track_competency', '니즈 파악 — 첫걸음', '지인 한 명에게 최근 산 물건의 이유를 "왜?"로 세 번 이어서 물어보세요. 말 뒤의 진짜 이유를 듣는 연습이 됩니다.'),
('TRK-persuasion_sales-H', 'track_competency', '설득·제안 — 강점으로 보여 주기', '고객 관점으로 가치를 말하고 반론에도 논리적으로 대처하는 힘이 강점입니다. 직접 쓴 제안서나 견적서와 협상 사례를 포트폴리오로 정리해 두세요.'),
('TRK-persuasion_sales-M', 'track_competency', '설득·제안 — 다음에 더할 것', '가치를 설명하는 기본기가 있습니다. 가상의 제품 제안서 한 장을 써 보고, 예상 반론 다섯 가지에 대한 답변을 미리 적어 연습해 보세요.'),
('TRK-persuasion_sales-L', 'track_competency', '설득·제안 — 첫걸음', '내가 아끼는 물건을 "친구에게 어떤 점이 좋은지" 세 문장으로 설명해 보세요. 기능이 아니라 상대에게 주는 이득으로 말하는 연습입니다.'),
('TRK-relationship-H', 'track_competency', '관계 관리 — 강점으로 보여 주기', '첫 만남에서 신뢰를 쌓고 거절에서도 빨리 회복하는 힘이 강점입니다. 불만을 기회로 바꾼 경험과 비대면으로 관계를 이어 간 사례를 구체적으로 정리해 보세요.'),
('TRK-relationship-M', 'track_competency', '관계 관리 — 다음에 더할 것', '사람을 편하게 대하는 힘이 있습니다. 만난 사람에게 24시간 안에 감사 메일을 보내는 습관을 들이고, 업계 행사나 학회에서 두 명과 대화해 보세요.'),
('TRK-relationship-L', 'track_competency', '관계 관리 — 첫걸음', '관심 분야 모임이나 온라인 세미나 하나에 참여해 한 사람에게 먼저 인사를 건네 보세요. 짧은 대화 한 번이 첫걸음입니다.'),
('TRK-pipeline_mgmt-H', 'track_competency', '파이프라인 관리 — 강점으로 보여 주기', '영업 단계를 관리하고 데이터로 전략을 고치는 힘이 강점입니다. 목표 설정, 단계별 전환 숫자, 개선한 점을 보고서 한 장으로 정리해 두세요.'),
('TRK-pipeline_mgmt-M', 'track_competency', '파이프라인 관리 — 다음에 더할 것', '영업 흐름을 이해하고 있습니다. 무료 CRM 도구에 가상의 고객 열 명을 리드에서 체결까지 단계별로 입력하고, 단계마다 걸리는 기간을 계산해 보세요.'),
('TRK-pipeline_mgmt-L', 'track_competency', '파이프라인 관리 — 첫걸음', '리드, 기회, 제안, 체결이 각각 무엇인지 한 줄씩 정리하고, 스프레드시트에 단계 칸을 만들어 가상 고객을 옮겨 보세요.'),
('TRK-biz_development-H', 'track_competency', '사업 개발 — 강점으로 보여 주기', '파트너를 발굴하고 기회의 우선순위를 가리는 힘이 강점입니다. 새 채널을 개척한 과정과 평가 기준, 협업으로 만든 성과를 숫자와 함께 정리해 보여 주세요.'),
('TRK-biz_development-M', 'track_competency', '사업 개발 — 다음에 더할 것', '기회를 찾는 감각이 있습니다. 관심 기업 다섯 곳에 제휴 제안 메일 초안을 써 보고, 기회를 비교하는 평가 기준 세 가지를 직접 정해 보세요.'),
('TRK-biz_development-L', 'track_competency', '사업 개발 — 첫걸음', '좋아하는 브랜드 두 곳의 협업 사례를 찾아 "서로 무엇을 얻었나"를 적어 보세요. 파트너십의 이유가 보이기 시작합니다.'),
('TRK-sales_comm-H', 'track_competency', '영업 커뮤니케이션 — 강점으로 보여 주기', '간결하고 설득력 있게 발표하고 맞춤 제안을 설계하는 힘이 강점입니다. 발표 영상이나 자료, 고객 상황에 맞춰 제안을 바꾼 사례를 함께 준비해 두세요.'),
('TRK-sales_comm-M', 'track_competency', '영업 커뮤니케이션 — 다음에 더할 것', '말하는 기본기가 있습니다. 같은 제안을 3분 버전과 30초 버전으로 나눠 녹음해 들어 보고, 고객 상황별로 어떤 부분을 바꿀지 적어 보세요.'),
('TRK-sales_comm-L', 'track_competency', '영업 커뮤니케이션 — 첫걸음', '복잡한 내용을 세 문장으로 줄여 가족이나 친구에게 말해 보세요. 이해했는지 물어보는 것만으로도 좋은 연습이 됩니다.'),
-- hr_org
('TRK-recruiting-H', 'track_competency', '채용 — 강점으로 보여 주기', '채용 과정을 설계하고 직무 기술서를 쓰는 힘이 강점입니다. 직접 쓴 JD나 면접 질문지를 포트폴리오에 넣고, 왜 그렇게 설계했는지 설명해 보세요.'),
('TRK-recruiting-M', 'track_competency', '채용 — 다음에 더할 것', '채용 흐름은 이해하고 있습니다. 관심 직무의 공개 공고를 읽고 구조화 면접 질문 다섯 개를 직접 만들어 보세요.'),
('TRK-recruiting-L', 'track_competency', '채용 — 첫걸음', '관심 기업의 채용 공고 세 개를 비교해 공통 요건과 다른 점을 표로 정리해 보세요. 직무 기술서가 어떻게 쓰이는지 보입니다.'),
('TRK-people_mgmt-H', 'track_competency', '인사 운영 — 강점으로 보여 주기', '평가 체계와 피드백, 온보딩을 이해하는 힘이 강점입니다. 온보딩 개선안이나 피드백 양식을 만든 사례를 면접에서 구체적으로 풀어 보세요.'),
('TRK-people_mgmt-M', 'track_competency', '인사 운영 — 다음에 더할 것', 'OKR과 KPI 같은 평가 틀은 알고 있습니다. 동아리나 팀 프로젝트에 OKR을 적용해 보고 무엇이 어려웠는지 기록해 보세요.'),
('TRK-people_mgmt-L', 'track_competency', '인사 운영 — 첫걸음', 'MBO, OKR, KPI의 차이를 한 장으로 정리해 보세요. 이번 주에 친구 한 명에게 건설적인 피드백을 주고받는 연습도 해 보세요.'),
('TRK-learning_dev-H', 'track_competency', '교육·육성 — 강점으로 보여 주기', '교육을 기획하고 효과를 따져 보는 힘이 있습니다. 직접 운영한 교육이나 멘토링의 목표와 결과를 Kirkpatrick 4단계에 맞춰 정리해 두세요.'),
('TRK-learning_dev-M', 'track_competency', '교육·육성 — 다음에 더할 것', '교육과 멘토링을 경험했습니다. 직무 하나의 필요 역량을 정의하고 성장 경로를 그려 보는 연습을 더해 보세요.'),
('TRK-learning_dev-L', 'track_competency', '교육·육성 — 첫걸음', '관심 직무의 공개 채용 공고에서 요구 역량을 뽑아 초급에서 중급으로 가는 성장 경로를 간단히 그려 보세요.'),
('TRK-org_culture-H', 'track_competency', '조직문화 — 강점으로 보여 주기', '문화를 진단하고 갈등과 변화를 다루는 이해가 강점입니다. 팀 활동에서 갈등을 풀었던 경험을 변화 관리 모델에 맞춰 정리해 두세요.'),
('TRK-org_culture-M', 'track_competency', '조직문화 — 다음에 더할 것', '문화의 구성 요소는 알고 있습니다. 하이브리드 근무를 하는 기업 사례 하나를 골라 어떤 제도가 문화를 받치는지 분석해 보세요.'),
('TRK-org_culture-L', 'track_competency', '조직문화 — 첫걸음', '내가 속한 동아리나 팀의 일하는 방식을 다섯 줄로 적어 보세요. 눈에 보이지 않는 문화를 말로 꺼내 보는 연습입니다.'),
('TRK-hr_analytics-H', 'track_competency', 'HR 데이터 — 강점으로 보여 주기', '인사 지표를 읽고 활용하는 힘이 강점입니다. 이직률이나 채용 전환율 같은 지표를 분석해 개선안을 낸 사례를 한 장으로 보여 주세요.'),
('TRK-hr_analytics-M', 'track_competency', 'HR 데이터 — 다음에 더할 것', '피플 애널리틱스의 개념은 압니다. 공개된 인사 통계로 엑셀 표를 만들고 숫자가 말하는 내용을 두세 줄로 해석해 보세요.'),
('TRK-hr_analytics-L', 'track_competency', 'HR 데이터 — 첫걸음', '이직률, 채용 전환율, 몰입도 점수가 각각 무엇을 재는지 한 줄씩 정리하는 것부터 시작하세요. 이번 주에 15분이면 됩니다.'),
('TRK-hr_legal-H', 'track_competency', '노무·법규 — 강점으로 보여 주기', '근로기준법과 급여, 4대 보험을 이해하는 점이 강점입니다. 근로계약서 핵심 조항을 직접 해설한 자료를 만들어 두면 기본기가 보입니다.'),
('TRK-hr_legal-M', 'track_competency', '노무·법규 — 다음에 더할 것', '노동법의 기본은 알고 있습니다. 고용노동부 공개 자료로 직장 내 괴롭힘 예방 의무와 고용 형태별 차이를 표로 정리해 보세요.'),
('TRK-hr_legal-L', 'track_competency', '노무·법규 — 첫걸음', '내 아르바이트 근로계약서나 표준근로계약서 양식을 읽고 근로시간, 임금, 휴가 항목을 찾아 표시해 보세요.'),
-- service_cx
('TRK-customer_empathy-H', 'track_competency', '고객 공감 — 강점으로 보여 주기', '불만을 먼저 받아 주고 진짜 니즈를 읽는 힘이 강점입니다. 어려운 응대를 풀어낸 경험을 상황, 내가 한 말, 결과 순서로 정리해 두세요.'),
('TRK-customer_empathy-M', 'track_competency', '고객 공감 — 다음에 더할 것', '공감하는 태도는 갖추고 있습니다. 유형별 응대 문구를 직접 써 보고, 채팅이나 이메일에서 따뜻함이 전해지는지 점검해 보세요.'),
('TRK-customer_empathy-L', 'track_competency', '고객 공감 — 첫걸음', '최근 내가 불만을 가졌던 서비스를 떠올려 어떤 말을 들었으면 풀렸을지 세 줄로 적어 보세요. 고객 입장에서 보는 연습입니다.'),
('TRK-cs_operation-H', 'track_competency', 'CS 운영 — 강점으로 보여 주기', '매뉴얼과 도구, 품질 점검을 다루는 힘이 있습니다. FAQ나 응대 매뉴얼, 문의를 줄인 개선 제안을 전후 비교로 보여 주세요.'),
('TRK-cs_operation-M', 'track_competency', 'CS 운영 — 다음에 더할 것', 'CS 운영의 기본은 알고 있습니다. 자주 묻는 질문 열 개를 모아 FAQ 문서로 써 보고, 챗봇이 대신하기 어려운 문의를 구분해 보세요.'),
('TRK-cs_operation-L', 'track_competency', 'CS 운영 — 첫걸음', '관심 서비스의 FAQ 페이지를 읽고 질문이 어떤 순서와 말투로 정리돼 있는지 살펴보세요. 무료 채팅 도구 체험판을 써 봐도 좋습니다.'),
('TRK-cx_design-H', 'track_competency', 'CX 설계 — 강점으로 보여 주기', '고객 여정과 터치포인트를 분석하는 힘이 강점입니다. 여정 지도와 NPS·CSAT 같은 지표를 엮은 개선안을 한 장으로 정리해 두세요.'),
('TRK-cx_design-M', 'track_competency', 'CX 설계 — 다음에 더할 것', '지표와 여정 개념은 이해합니다. 서비스 하나의 블루프린트를 직접 그리고, 불만이 생기면 어떻게 회복할지 계획을 더해 보세요.'),
('TRK-cx_design-L', 'track_competency', 'CX 설계 — 첫걸음', '자주 쓰는 앱의 가입부터 첫 구매까지 단계를 적고, 각 단계에서 느낀 감정을 표시해 보세요. 여정 지도의 기본 모양입니다.'),
('TRK-cx_analytics-H', 'track_competency', 'CX 분석 — 강점으로 보여 주기', '고객 데이터에서 개선점을 뽑는 힘이 강점입니다. VOC를 분류하고 우선순위를 매겨 제안한 과정을 표와 결론으로 보여 주세요.'),
('TRK-cx_analytics-M', 'track_competency', 'CX 분석 — 다음에 더할 것', '분석의 기본은 갖췄습니다. 앱 리뷰 백 개를 모아 주제별로 분류하고 가장 큰 불만 세 가지를 뽑는 연습을 더해 보세요.'),
('TRK-cx_analytics-L', 'track_competency', 'CX 분석 — 첫걸음', '관심 앱의 공개 리뷰 스무 개를 읽고 칭찬과 불만으로 나눠 세어 보세요. VOC 분류가 어떤 작업인지 감이 잡힙니다.'),
('TRK-service_resilience-H', 'track_competency', '서비스 회복력 — 강점으로 보여 주기', '여러 요청을 정리하고 악성 민원에도 절차대로 대응하는 힘이 강점입니다. 압박 상황을 침착하게 풀어낸 경험을 면접 사례로 준비하세요.'),
('TRK-service_resilience-M', 'track_competency', '서비스 회복력 — 다음에 더할 것', '침착하게 대응하는 기반은 있습니다. 요청 여러 개가 겹친 상황을 가정해 처리 순서와 이유를 적어 보는 연습을 더해 보세요.'),
('TRK-service_resilience-L', 'track_competency', '서비스 회복력 — 첫걸음', '긴장되는 상황에서 쓸 수 있는 호흡이나 한마디 문구를 하나 정해 이번 주에 연습해 보세요. 감정과 응대를 분리하는 첫 단계입니다.'),
('TRK-cx_leadership-H', 'track_competency', 'CX 리더십 — 강점으로 보여 주기', '팀을 이끌고 고객 관점을 조직에 전하는 힘이 강점입니다. 신입 교육이나 SOP를 만든 경험을 결과와 함께 정리해 두세요.'),
('TRK-cx_leadership-M', 'track_competency', 'CX 리더십 — 다음에 더할 것', '고객 중심 사고를 갖추고 있습니다. 동아리 활동에서 후배 안내 자료나 간단한 업무 절차서를 직접 써 보는 연습을 더해 보세요.'),
('TRK-cx_leadership-L', 'track_competency', 'CX 리더십 — 첫걸음', '옴니채널과 프로액티브 서비스 사례를 기사에서 하나 찾아 읽고, 팀이 어떻게 일하는지 세 줄로 요약해 보세요.'),
-- finance_planning
('TRK-financial_analysis-H', 'track_competency', '재무 분석 — 강점으로 보여 주기', '재무제표와 가치 평가를 읽는 힘이 강점입니다. 상장사 하나를 골라 비율 분석과 엑셀 모델을 정리한 분석 자료로 보여 주세요.'),
('TRK-financial_analysis-M', 'track_competency', '재무 분석 — 다음에 더할 것', '재무제표 읽기의 기본은 갖췄습니다. 같은 업종 두 회사의 ROE와 부채비율을 DART 공시로 비교하고 차이의 이유를 써 보세요.'),
('TRK-financial_analysis-L', 'track_competency', '재무 분석 — 첫걸음', '금융감독원 DART에서 관심 기업의 손익계산서 한 쪽을 열어 매출과 영업이익이 어떻게 변했는지 두 줄로 적어 보세요.'),
('TRK-corporate_finance-H', 'track_competency', '기업 재무 — 강점으로 보여 주기', '자본 구조와 투자 결정의 틀을 이해하는 점이 강점입니다. NPV와 IRR로 가상의 투자안을 평가한 엑셀 파일을 설명과 함께 준비하세요.'),
('TRK-corporate_finance-M', 'track_competency', '기업 재무 — 다음에 더할 것', '기업 재무의 큰 흐름은 알고 있습니다. 가상의 프로젝트 현금흐름으로 NPV를 계산해 보고 할인율이 달라지면 결론이 어떻게 변하는지 보세요.'),
('TRK-corporate_finance-L', 'track_competency', '기업 재무 — 첫걸음', '부채와 자기자본의 차이를 사례 기업 하나의 재무상태표에서 찾아보세요. 엑셀로 NPV 함수를 한 번 써 보는 것도 좋습니다.'),
('TRK-fin_reporting-H', 'track_competency', '재무 보고 — 강점으로 보여 주기', '숫자를 시각화하고 핵심만 요약하는 힘이 강점입니다. 피벗 테이블로 만든 한 장짜리 경영 보고서를 포트폴리오에 넣어 두세요.'),
('TRK-fin_reporting-M', 'track_competency', '재무 보고 — 다음에 더할 것', '엑셀과 보고 형식은 익숙합니다. 공개 재무 데이터를 피벗 테이블로 요약하고, 의사결정자가 볼 세 줄 요약을 붙여 보세요.'),
('TRK-fin_reporting-L', 'track_competency', '재무 보고 — 첫걸음', '엑셀 무료 실습 자료로 피벗 테이블과 VLOOKUP을 한 번씩 따라 해 보세요. 작은 표 하나를 보고서 한 줄로 요약하는 연습도 좋습니다.'),
('TRK-investment-H', 'track_competency', '투자 — 강점으로 보여 주기', '금융 상품과 거시 지표, 분산의 원리를 이해하는 점이 강점입니다. 가상 포트폴리오를 구성한 근거와 리스크 해석을 학습 기록으로 남겨 두세요.'),
('TRK-investment-M', 'track_competency', '투자 — 다음에 더할 것', '상품과 지표의 기본은 알고 있습니다. 한국은행 경제통계시스템에서 금리와 환율 추이를 내려받아 시장과의 관계를 정리해 보세요.'),
('TRK-investment-L', 'track_competency', '투자 — 첫걸음', '주식, 채권, 펀드의 차이를 한 장으로 정리하고 한국은행 통계에서 기준금리 추이를 한 번 확인해 보세요. 학습 목적의 정리면 충분합니다.'),
('TRK-compliance-H', 'track_competency', '컴플라이언스 — 강점으로 보여 주기', '금융 규제와 내부통제, AML·KYC를 이해하는 점이 강점입니다. 규제 사례 하나를 골라 배경과 통제 방안을 정리한 요약 자료를 준비하세요.'),
('TRK-compliance-M', 'track_competency', '컴플라이언스 — 다음에 더할 것', '규제의 큰 틀은 알고 있습니다. 금융위원회나 금융감독원의 공개 제재 사례를 읽고 어떤 통제가 부족했는지 정리해 보세요.'),
('TRK-compliance-L', 'track_competency', '컴플라이언스 — 첫걸음', '자금세탁방지와 고객확인이 왜 필요한지, 금융감독원 안내 자료에서 쉬운 설명을 하나 읽고 세 줄로 요약해 보세요.'),
('TRK-fintech-H', 'track_competency', '핀테크 — 강점으로 보여 주기', '핀테크 구조와 금융 API 생태계를 파악하는 점이 강점입니다. 서비스 하나의 수익 구조와 데이터 흐름을 도식으로 그려 두세요.'),
('TRK-fintech-M', 'track_competency', '핀테크 — 다음에 더할 것', '디지털 금융 흐름은 알고 있습니다. 간편결제와 마이데이터 서비스를 직접 써 보고 데이터가 어떻게 연결되는지 정리해 보세요.'),
('TRK-fintech-L', 'track_competency', '핀테크 — 첫걸음', '오픈뱅킹과 마이데이터가 무엇인지 금융위원회 안내 자료로 읽고, 내가 쓰는 금융 앱 중 해당하는 기능을 찾아보세요.'),
-- legal_professional
('TRK-legal_knowledge-H', 'track_competency', '법률 지식 — 강점으로 보여 주기', '민법·상법·형법의 체계와 판례 쟁점을 파악하는 힘이 강점입니다. 관심 분야 판례 해설 노트를 쓴 기록으로 깊이를 보여 주세요.'),
('TRK-legal_knowledge-M', 'track_competency', '법률 지식 — 다음에 더할 것', '법 체계의 기본은 갖췄습니다. 관심 분야 법 한 가지를 정해 최근 개정 내용을 국가법령정보센터에서 확인하고 요약해 보세요.'),
('TRK-legal_knowledge-L', 'track_competency', '법률 지식 — 첫걸음', '국가법령정보센터에서 민법 조문 하나를 읽고, 일상 사례에 대입해 두 줄로 설명해 보세요. 조문 읽기에 익숙해지는 연습입니다.'),
('TRK-legal_research-H', 'track_competency', '리서치 — 강점으로 보여 주기', '법률 데이터베이스를 쓰고 결과를 정리하는 힘이 강점입니다. 쟁점별 조문과 판례를 정리한 리서치 메모를 샘플로 준비해 두세요.'),
('TRK-legal_research-M', 'track_competency', '리서치 — 다음에 더할 것', '검색 도구는 다룰 수 있습니다. 한 쟁점의 판례 다섯 건을 찾아 결론과 이유를 표로 비교하는 연습을 더해 보세요.'),
('TRK-legal_research-L', 'track_competency', '리서치 — 첫걸음', '대법원 종합법률정보에서 관심 키워드로 판결문 하나를 찾아 사건 개요와 결론을 다섯 줄로 요약해 보세요.'),
('TRK-contract_drafting-H', 'track_competency', '계약 작성 — 강점으로 보여 주기', '계약 핵심 조항을 읽고 위험 지점을 찾는 힘이 강점입니다. 공개된 표준계약서를 검토한 의견을 학습 자료로 정리해 두세요.'),
('TRK-contract_drafting-M', 'track_competency', '계약 작성 — 다음에 더할 것', '조항의 의미는 이해합니다. 공정거래위원회의 표준계약서 하나를 골라 해지와 분쟁해결 조항에서 주의할 점을 적어 보세요.'),
('TRK-contract_drafting-L', 'track_competency', '계약 작성 — 첫걸음', '공정거래위원회 공개 표준계약서에서 당사자, 대금, 해지 조항을 찾아 표시해 보세요. 계약서의 뼈대가 보입니다.'),
('TRK-litigation-H', 'track_competency', '분쟁·소송 — 강점으로 보여 주기', '소송 절차를 알고 주장을 논리적으로 쓰는 힘이 강점입니다. 모의재판이나 사례 분석에서 쓴 주장 문서를 구조와 함께 보여 주세요.'),
('TRK-litigation-M', 'track_competency', '분쟁·소송 — 다음에 더할 것', '절차의 흐름은 알고 있습니다. 가상 분쟁을 두고 사실, 쟁점, 주장 순서로 짧은 글을 써 보고 비전문가에게 설명하는 연습을 더해 보세요.'),
('TRK-litigation-L', 'track_competency', '분쟁·소송 — 첫걸음', '소장에서 판결까지 절차를 대한민국 법원 안내 페이지로 읽고 단계별로 한 줄씩 정리해 보세요. 조정 같은 대안도 함께 확인해 보세요.'),
('TRK-ip_law-H', 'track_competency', '지식재산 — 강점으로 보여 주기', '특허·상표·저작권의 차이와 보호 방식을 이해하는 점이 강점입니다. 사례 하나를 골라 어떤 권리가 어떻게 보호되는지 정리해 보여 주세요.'),
('TRK-ip_law-M', 'track_competency', '지식재산 — 다음에 더할 것', '권리 유형은 구분합니다. 특허정보 검색 서비스 키프리스(KIPRIS)에서 공개 특허 하나를 읽고 청구항이 무엇을 보호하는지 설명해 보세요.'),
('TRK-ip_law-L', 'track_competency', '지식재산 — 첫걸음', '특허, 상표, 디자인, 저작권을 한 표로 비교해 보세요. 한국지식재산보호원 등의 공개 안내 자료를 참고하면 됩니다.'),
('TRK-compliance_legal-H', 'track_competency', '준법 — 강점으로 보여 주기', '개인정보보호법과 공정거래법 등 준법 체계를 이해하는 점이 강점입니다. 기업 규제 변화의 리스크를 정리한 분석 메모를 보여 주세요.'),
('TRK-compliance_legal-M', 'track_competency', '준법 — 다음에 더할 것', '준법의 구조는 이해합니다. 개인정보보호위원회 공개 처분 사례를 읽고 어떤 의무를 놓쳤는지 정리하는 연습을 더해 보세요.'),
('TRK-compliance_legal-L', 'track_competency', '준법 — 첫걸음', '개인정보보호위원회 공개 안내 자료에서 개인정보 처리 원칙을 읽고, 내가 쓰는 서비스의 처리방침에서 같은 항목을 찾아보세요.'),
-- education_training
('TRK-teaching-H', 'track_competency', '강의·전달 — 강점으로 보여 주기', '강의를 구조적으로 짜고 참여를 이끄는 힘이 강점입니다. 직접 만든 슬라이드와 시간표, 수강생 반응을 묶어 샘플 강의로 보여 주세요.'),
('TRK-teaching-M', 'track_competency', '강의·전달 — 다음에 더할 것', '전달의 기본기는 있습니다. 10분 미니 강의를 녹화해 보고 토론이나 퀴즈 같은 참여 장치를 하나 넣어 다시 해 보세요.'),
('TRK-teaching-L', 'track_competency', '강의·전달 — 첫걸음', '내가 아는 주제 하나를 도입, 본론, 정리로 나눠 5분 분량 개요를 써 보고 친구에게 설명해 보세요.'),
('TRK-curriculum_design-H', 'track_competency', '커리큘럼 설계 — 강점으로 보여 주기', '학습 목표에서 과정을 짜는 힘이 강점입니다. 블룸 분류에 맞춘 학습 목표와 차시 계획을 한 장으로 정리해 포트폴리오에 넣으세요.'),
('TRK-curriculum_design-M', 'track_competency', '커리큘럼 설계 — 다음에 더할 것', '설계의 틀은 이해합니다. 한 주제로 초급과 중급 두 과정을 짜서 난이도가 어떻게 달라지는지 비교해 보세요.'),
('TRK-curriculum_design-L', 'track_competency', '커리큘럼 설계 — 첫걸음', '공개 온라인 강좌 하나의 목차를 보고 각 차시의 학습 목표를 동사로 한 줄씩 적어 보세요. 블룸 분류와 연결해 보면 좋습니다.'),
('TRK-assessment-H', 'track_competency', '평가 — 강점으로 보여 주기', '평가 도구를 설계하고 결과를 개선에 쓰는 힘이 강점입니다. 직접 만든 루브릭과 설문 결과 분석을 사례로 정리해 두세요.'),
('TRK-assessment-M', 'track_competency', '평가 — 다음에 더할 것', '형성 평가와 총괄 평가의 차이는 압니다. 과제 하나에 4단계 루브릭을 직접 만들고 동료에게 써 보게 해 보세요.'),
('TRK-assessment-L', 'track_competency', '평가 — 첫걸음', '공개된 루브릭 양식 하나를 찾아 평가 항목과 단계 기준이 어떻게 나뉘는지 읽어 보세요. 만족도 설문 질문 다섯 개도 써 보세요.'),
('TRK-learner_support-H', 'track_competency', '학습자 지원 — 강점으로 보여 주기', '동기를 읽고 부진 학습자를 돕는 힘이 강점입니다. 멘토링이나 학습 커뮤니티를 운영한 경험을 대상, 지원 방법, 변화로 정리하세요.'),
('TRK-learner_support-M', 'track_competency', '학습자 지원 — 다음에 더할 것', '학습자를 돕는 감각이 있습니다. 한 사람을 정해 목표를 함께 세우고 4주간 점검하는 소규모 멘토링을 시도해 보세요.'),
('TRK-learner_support-L', 'track_competency', '학습자 지원 — 첫걸음', '스터디나 동아리에서 막혀 있는 사람에게 이번 주에 먼저 어려운 점을 물어보고 한 가지 도움을 건네 보세요.'),
('TRK-edtech-H', 'track_competency', '에듀테크 — 강점으로 보여 주기', 'LMS와 영상, 인터랙티브 콘텐츠를 다루는 힘이 강점입니다. 직접 만든 강의 영상이나 퀴즈 콘텐츠를 링크와 설명으로 모아 두세요.'),
('TRK-edtech-M', 'track_competency', '에듀테크 — 다음에 더할 것', '디지털 도구를 접해 봤습니다. 무료 도구로 퀴즈 콘텐츠를 만들고 게이미피케이션 요소를 하나 넣어 효과를 관찰해 보세요.'),
('TRK-edtech-L', 'track_competency', '에듀테크 — 첫걸음', '무료 LMS나 퀴즈 도구의 체험 계정으로 문제 세 개짜리 퀴즈를 만들어 보세요. 학습자가 보는 화면을 직접 확인하는 것이 핵심입니다.'),
('TRK-edu_business-H', 'track_competency', '교육 사업 — 강점으로 보여 주기', '모집, 가격, 강사 섭외를 사업으로 보는 힘이 강점입니다. 프로그램을 기획해 모집한 과정을 수치와 함께 사례로 정리해 두세요.'),
('TRK-edu_business-M', 'track_competency', '교육 사업 — 다음에 더할 것', '교육 사업의 구조는 이해합니다. 교육 프로그램 하나의 수강료, 정원, 비용을 가정해 손익을 계산하는 연습을 더해 보세요.'),
('TRK-edu_business-L', 'track_competency', '교육 사업 — 첫걸음', '관심 있는 교육 프로그램의 모집 페이지를 읽고 대상, 가격, 홍보 문구를 정리해 보세요. 정부 지원 교육 제도도 하나 찾아보세요.'),
-- media_broadcast
('TRK-program_planning-H', 'track_competency', '프로그램 기획 — 강점으로 보여 주기', '시청자를 분석해 기획안을 쓰는 힘이 강점입니다. 직접 쓴 기획안과 큐시트를 타깃 분석과 함께 포트폴리오로 묶어 보여 주세요.'),
('TRK-program_planning-M', 'track_competency', '프로그램 기획 — 다음에 더할 것', '기획안을 쓸 수 있습니다. 장르를 달리해 같은 소재로 예능형과 다큐형 기획안을 각각 써 보며 차이를 익혀 보세요.'),
('TRK-program_planning-L', 'track_competency', '프로그램 기획 — 첫걸음', '좋아하는 프로그램 한 회차의 구성을 시간순으로 적어 큐시트 모양으로 만들어 보세요. 방송이 어떻게 짜이는지 구조가 보입니다.'),
('TRK-production_media-H', 'track_competency', '촬영·현장 제작 — 강점으로 보여 주기', '카메라, 조명, 음향을 이해하고 현장에 대응하는 힘이 강점입니다. 직접 촬영한 영상과 촬영 스케줄표를 함께 보여 주세요.'),
('TRK-production_media-M', 'track_competency', '촬영·현장 제작 — 다음에 더할 것', '촬영 기본기는 있습니다. 스마트폰으로 3점 조명을 흉내 낸 인터뷰 촬영을 해 보고 소리 품질까지 점검해 보세요.'),
('TRK-production_media-L', 'track_competency', '촬영·현장 제작 — 첫걸음', '스마트폰으로 같은 장소를 자연광이 다른 시간대에 두 번 찍어 보세요. 빛이 영상 분위기를 바꾸는 것을 직접 확인할 수 있습니다.'),
('TRK-post_production-H', 'track_competency', '후반 작업 — 강점으로 보여 주기', '편집으로 이야기 흐름을 만드는 힘이 강점입니다. 편집한 영상 두세 편을 릴 하나로 묶고, 편집 의도를 한 줄씩 붙여 두세요.'),
('TRK-post_production-M', 'track_competency', '후반 작업 — 다음에 더할 것', '편집 도구를 다룰 수 있습니다. 같은 영상을 색보정과 자막, 간단한 모션그래픽까지 넣어 완성도를 한 단계 올려 보세요.'),
('TRK-post_production-L', 'track_competency', '후반 작업 — 첫걸음', '무료 편집 프로그램으로 1분 영상을 컷 편집하고 자막을 넣어 보세요. 해상도와 파일 형식 설정도 한 번 확인해 보세요.'),
('TRK-journalism-H', 'track_competency', '취재·보도 — 강점으로 보여 주기', '사실을 확인하고 목적에 맞게 쓰는 힘이 강점입니다. 취재와 인터뷰로 쓴 기사나 대본에 출처 확인 과정을 함께 정리해 보여 주세요.'),
('TRK-journalism-M', 'track_competency', '취재·보도 — 다음에 더할 것', '글쓰기와 취재의 기본은 있습니다. 같은 사건을 방송 원고와 인쇄 기사로 각각 써서 호흡과 문장 길이의 차이를 익혀 보세요.'),
('TRK-journalism-L', 'track_competency', '취재·보도 — 첫걸음', '공개된 보도 하나를 골라 출처가 어디인지 직접 따라가며 확인해 보세요. 팩트체크의 기본 습관이 만들어집니다.'),
('TRK-digital_media-H', 'track_competency', '디지털 미디어 — 강점으로 보여 주기', '플랫폼별 전략과 성과 지표를 읽는 힘이 강점입니다. 운영한 채널의 조회수와 시청시간 분석을 개선 사례로 정리해 두세요.'),
('TRK-digital_media-M', 'track_competency', '디지털 미디어 — 다음에 더할 것', '플랫폼 감각은 있습니다. 같은 콘텐츠를 숏폼과 롱폼으로 각각 만들어 보고 반응 지표 차이를 비교해 보세요.'),
('TRK-digital_media-L', 'track_competency', '디지털 미디어 — 첫걸음', '좋아하는 크리에이터 한 팀의 영상 열 편을 보고 길이, 제목, 오프닝 방식의 공통점을 표로 정리해 보세요.'),
('TRK-media_industry-H', 'track_competency', '미디어 산업 이해 — 강점으로 보여 주기', '제작 분업과 수익 구조, 저작권을 이해하는 점이 강점입니다. 프로그램 하나의 제작 인력과 수익 구조를 분석한 글로 보여 주세요.'),
('TRK-media_industry-M', 'track_competency', '미디어 산업 이해 — 다음에 더할 것', '산업 구조는 알고 있습니다. 한국콘텐츠진흥원의 공개 산업 보고서를 읽고 광고, 구독, 제작비 흐름을 한 장으로 요약해 보세요.'),
('TRK-media_industry-L', 'track_competency', '미디어 산업 이해 — 첫걸음', '좋아하는 프로그램의 엔딩 크레딧을 보고 PD, 작가, 촬영, 편집이 각각 맡은 일을 찾아 한 줄씩 적어 보세요.'),
-- construction_build
('TRK-architectural_design-H', 'track_competency', '설계 — 강점으로 보여 주기', '도면을 읽고 법규와 구조 원리까지 이해하는 힘이 강점입니다. 수업이나 공모전에서 그린 도면 한 세트에 건폐율·용적률 검토와 시공팀을 위한 설명 메모를 붙여 포트폴리오에 넣어 보세요.'),
('TRK-architectural_design-M', 'track_competency', '설계 — 다음에 더할 것', '도면을 읽는 기본기는 있습니다. 공개된 소형 건축물 도면 한 세트로 평면·입면·단면을 대조하며 읽고, Revit 같은 BIM 도구의 무료 체험판으로 간단한 모델을 만들어 보세요.'),
('TRK-architectural_design-L', 'track_competency', '설계 — 첫걸음', '이번 주에 관심 있는 건물의 공개 평면도 한 장을 찾아 방과 복도의 위치를 직접 따라 그려 보세요. 건축법상 건폐율과 용적률의 뜻도 국가법령정보센터에서 함께 찾아보세요.'),
('TRK-construction_mgmt-H', 'track_competency', '시공 관리 — 강점으로 보여 주기', '공정과 비용, 하도급까지 아우르는 관리 감각이 강점입니다. 직접 만든 공정표나 공사비 산출 사례를 정리하고 설계 변경 때 어떻게 대응했는지 면접에서 설명할 수 있게 준비하세요.'),
('TRK-construction_mgmt-M', 'track_competency', '시공 관리 — 다음에 더할 것', '공정과 예산의 기본은 이해하고 있습니다. 가상의 소규모 공사를 정해 간트 차트로 공정표를 만들고, 설계가 바뀌면 일정과 비용이 어떻게 달라지는지 직접 계산해 보세요.'),
('TRK-construction_mgmt-L', 'track_competency', '시공 관리 — 첫걸음', '엑셀로 집 리모델링 같은 작은 일을 가정해 작업 순서와 기간을 간트 차트로 그려 보세요. 공정표가 왜 필요한지, 순서가 바뀌면 무엇이 밀리는지 감이 잡힙니다.'),
('TRK-materials-H', 'track_competency', '자재 — 강점으로 보여 주기', '자재 특성과 공정 순서, 설비와 스마트 건설 흐름까지 아는 점이 강점입니다. 콘크리트·철근·철골의 선택 기준을 정리한 노트나 현장 견학 기록을 포트폴리오에 담아 보세요.'),
('TRK-materials-M', 'track_competency', '자재 — 다음에 더할 것', '주요 자재와 공정 순서는 알고 있습니다. 제로에너지 건축이나 녹색 건축 인증 사례를 하나 골라 어떤 자재와 설비를 썼는지 정리해 보면 지식이 한 단계 깊어집니다.'),
('TRK-materials-L', 'track_competency', '자재 — 첫걸음', '콘크리트, 철근, 철골이 각각 어떤 힘을 맡는지 한 줄씩 정리해 보세요. 공사 중인 건물이 있다면 기초에서 골조, 마감으로 가는 순서를 지나가며 관찰해 보는 것도 좋습니다.'),
('TRK-safety_quality-H', 'track_competency', '안전·품질 — 강점으로 보여 주기', '산업안전보건법과 위험성 평가, 품질 검사를 이해하는 점이 강점입니다. 위험성 평가표를 직접 작성한 사례나 건설안전 관련 교육 이수 내역을 이력서에 구체적으로 적어 두세요.'),
('TRK-safety_quality-M', 'track_competency', '안전·품질 — 다음에 더할 것', '안전과 품질의 기준은 이해하고 있습니다. 한국산업안전보건공단의 공개 재해 사례 자료로 위험성 평가표를 연습해 보고, 건설업 기초안전보건교육 과정을 알아보세요.'),
('TRK-safety_quality-L', 'track_competency', '안전·품질 — 첫걸음', '산업안전보건법이 건설 현장에 요구하는 기본이 무엇인지 공단의 공개 안내서를 읽어 보세요. 현장 실습은 반드시 자격을 갖춘 지도자의 관리 아래에서만 하세요.'),
('TRK-site_leadership-H', 'track_competency', '현장 리더십 — 강점으로 보여 주기', '다양한 직종과 소통하고 돌발 상황에 대응하는 힘이 강점입니다. 팀 프로젝트나 인턴에서 이해관계를 조율했던 상황을 상황·행동·결과 순서로 정리해 면접에서 말할 수 있게 하세요.'),
('TRK-site_leadership-M', 'track_competency', '현장 리더십 — 다음에 더할 것', '현장 소통의 기본은 갖추고 있습니다. 건설 현장 인턴이나 견학 프로그램에 참여해 철근·목공·설비 담당자가 서로 어떻게 일정을 맞추는지 관찰하고 기록해 보세요.'),
('TRK-site_leadership-L', 'track_competency', '현장 리더십 — 첫걸음', '건설 현장 근무자의 하루를 다룬 인터뷰나 영상을 찾아보세요. 야외 근무와 체력 조건이 나에게 맞는지 생각해 보고, 현직자에게 질문할 목록을 세 가지 적어 보세요.'),
('TRK-supervision-H', 'track_competency', '감리 — 강점으로 보여 주기', '감리의 역할과 인허가 절차, 검측 포인트를 이해하는 점이 강점입니다. 설계도서와 현황이 다를 때의 보고 예시를 직접 써 보고, 건설기술인 자격 취득 계획을 이력서에 밝혀 두세요.'),
('TRK-supervision-M', 'track_competency', '감리 — 다음에 더할 것', '감리의 기본 역할은 알고 있습니다. 착공에서 준공까지 인허가 단계를 세움터 같은 공개 안내로 따라가 보고, 단계별 검측 항목을 표로 정리하는 연습을 더해 보세요.'),
('TRK-supervision-L', 'track_competency', '감리 — 첫걸음', '건설산업기본법과 건축법에서 감리가 어떤 일을 하는지 국가법령정보센터의 조문 제목만 먼저 훑어보세요. 시공자와 감리자의 책임이 어떻게 다른지 한 줄로 정리해 보세요.'),
-- manufacturing_ops
('TRK-mfg_leadership-H', 'track_competency', '현장 리더십 — 강점으로 보여 주기', '작업자 지시, 교대 변동 대응, 부서 간 조율에 강점이 있습니다. 여러 사람과 일정을 맞춘 팀 프로젝트나 아르바이트 사례를 문제 상황과 해결 결과 중심으로 이력서에 적어 보세요.'),
('TRK-mfg_leadership-M', 'track_competency', '현장 리더십 — 다음에 더할 것', '현장을 이끄는 기본 감각은 있습니다. 공장 견학이나 제조업 현직자 인터뷰로 설계·영업·품질 부서가 생산과 어떻게 부딪히고 조율하는지 사례를 모아 보세요.'),
('TRK-mfg_leadership-L', 'track_competency', '현장 리더십 — 첫걸음', '탄소 중립이나 리쇼어링처럼 제조업의 최근 변화를 다룬 기사 두 편을 읽고 현장에 어떤 영향이 있을지 세 줄로 적어 보세요. 교대 근무 직무 영상도 찾아보세요.'),
('TRK-process_improvement-H', 'track_competency', '공정 개선 — 강점으로 보여 주기', 'PDCA와 원가 분석, 스마트 팩토리까지 이해하는 점이 강점입니다. 개선에 참여한 경험을 개선 전후 수치로 정리하고 ERP 사용 경험이 있다면 시스템 이름과 함께 적어 두세요.'),
('TRK-process_improvement-M', 'track_competency', '공정 개선 — 다음에 더할 것', '개선의 개념은 알고 있습니다. 일상의 불편한 절차 하나를 골라 PDCA로 개선안을 써 보고, 개선 전후를 시간이나 횟수 같은 숫자로 비교하는 연습을 더해 보세요.'),
('TRK-process_improvement-L', 'track_competency', '공정 개선 — 첫걸음', '카이젠이 무엇인지 공개된 제조 기업 사례 하나를 읽어 보세요. 내 생활 속 번거로운 절차 하나를 골라 어떤 낭비가 있는지 세 가지만 적어 보세요.'),
('TRK-production_planning-H', 'track_competency', '생산 계획 — 강점으로 보여 주기', '생산 계획과 병목 파악, 가동률 분석에 강점이 있습니다. 가상의 공정으로 병목을 찾고 생산 계획을 짠 엑셀 파일을 만들어 포트폴리오에 넣으면 분석력이 구체적으로 보입니다.'),
('TRK-production_planning-M', 'track_competency', '생산 계획 — 다음에 더할 것', '계획의 기본 원리는 알고 있습니다. 공정 흐름도를 직접 그려 병목을 표시해 보고, JIT와 칸반이 재고와 리드타임에 어떻게 다르게 작용하는지 비교 정리해 보세요.'),
('TRK-production_planning-L', 'track_competency', '생산 계획 — 첫걸음', '라면이나 샌드위치처럼 쉬운 제품을 골라 만드는 단계를 순서대로 그려 보세요. 어느 단계가 가장 오래 걸리는지 표시하면 병목이라는 개념이 이해됩니다.'),
('TRK-quality_mgmt-H', 'track_competency', '품질 관리 — 강점으로 보여 주기', '관리도·파레토 같은 도구와 원인 추적에 강점이 있습니다. 불량 데이터를 파레토로 정리한 분석 사례를 포트폴리오에 넣고 품질경영기사 같은 관련 자격 취득 계획을 밝히세요.'),
('TRK-quality_mgmt-M', 'track_competency', '품질 관리 — 다음에 더할 것', '품질 도구의 개념은 알고 있습니다. 공개 데이터나 가상의 불량 데이터로 파레토 차트와 특성요인도를 직접 그려 보고, ISO 9001의 구조를 개요 수준으로 읽어 보세요.'),
('TRK-quality_mgmt-L', 'track_competency', '품질 관리 — 첫걸음', '6시그마와 린 제조가 각각 무엇을 줄이려는지 한 줄씩 정리해 보세요. 집에서 쓰는 제품의 불량 사례를 하나 떠올려 어디서 원인이 생겼을지 추론해 보는 것도 좋습니다.'),
('TRK-safety_env-H', 'track_competency', '안전·환경 — 강점으로 보여 주기', '산업안전보건법과 위험성 평가, 환경 규제를 두루 아는 점이 강점입니다. 안전 수칙이나 교육 자료를 직접 만든 경험을 정리하고 산업안전기사 같은 자격 계획을 이력서에 적어 두세요.'),
('TRK-safety_env-M', 'track_competency', '안전·환경 — 다음에 더할 것', '안전과 환경의 기본은 이해하고 있습니다. 공단의 공개 위험성 평가 서식으로 가상의 작업을 평가해 보고, ESG 관점에서 제조 공정을 개선한 기업 사례를 하나 정리해 보세요.'),
('TRK-safety_env-L', 'track_competency', '안전·환경 — 첫걸음', '한국산업안전보건공단의 공개 안내 자료에서 산업안전보건법의 기본 내용을 읽어 보세요. 작업 현장에서의 위험 작업은 반드시 교육과 자격을 갖춘 뒤에만 하세요.'),
('TRK-supply_chain-H', 'track_competency', '공급망 — 강점으로 보여 주기', '공급업체 평가와 구매 협상, 재고 관리에 강점이 있습니다. 평가 기준표를 직접 만든 사례나 협상 경험을 정리하고 글로벌 공급망 위기가 원가에 준 영향을 분석해 면접에서 이야기해 보세요.'),
('TRK-supply_chain-M', 'track_competency', '공급망 — 다음에 더할 것', '공급망의 기본은 알고 있습니다. 가격·품질·납기·안정성으로 가상의 공급업체 세 곳을 점수화해 비교해 보고, ABC 분석으로 재고 품목을 나누는 연습을 더해 보세요.'),
('TRK-supply_chain-L', 'track_competency', '공급망 — 첫걸음', '관심 있는 제품 하나의 원자재가 어디서 와서 어떻게 만들어지는지 거꾸로 추적해 적어 보세요. 공급업체를 고를 때 가격 말고 무엇을 볼지 세 가지를 생각해 보세요.'),
-- logistics_scm
('TRK-scm_basics-H', 'track_competency', 'SCM 기초 — 강점으로 보여 주기', '공급망 흐름과 수요 예측, 재고 전략을 이해하는 점이 강점입니다. 이동평균으로 수요를 예측하고 안전재고를 계산한 엑셀 사례를 만들어 재고회전율 같은 KPI와 함께 보여 주세요.'),
('TRK-scm_basics-M', 'track_competency', 'SCM 기초 — 다음에 더할 것', '공급망의 큰 그림은 알고 있습니다. 가상의 판매 데이터로 이동평균과 지수평활 예측을 직접 계산해 보고 결과 차이를 비교하면 개념이 숫자로 자리 잡습니다.'),
('TRK-scm_basics-L', 'track_competency', 'SCM 기초 — 첫걸음', '좋아하는 제품 하나가 원료에서 내 손까지 오는 과정을 단계별로 그려 보세요. 재고회전율과 리드타임이라는 용어의 뜻도 이번 주에 한 줄씩 정리해 보세요.'),
('TRK-logistics_ops-H', 'track_competency', '물류 운영 — 강점으로 보여 주기', '운송 모드와 창고 관리, 라스트마일을 이해하고 WMS·TMS 경험까지 있는 점이 강점입니다. 사용한 시스템 이름과 담당했던 업무를 구체적으로 적어 이력서에서 눈에 띄게 하세요.'),
('TRK-logistics_ops-M', 'track_competency', '물류 운영 — 다음에 더할 것', '운송과 창고의 기본은 알고 있습니다. 육상·해운·항공의 비용과 속도를 표로 비교해 보고 무료 WMS 체험 환경이나 시연 영상으로 입고에서 출고까지 흐름을 따라가 보세요.'),
('TRK-logistics_ops-L', 'track_competency', '물류 운영 — 첫걸음', '택배 한 건이 접수되어 배송 완료되기까지의 단계를 송장 조회 화면으로 따라가 보세요. 입고, 보관, 피킹, 출고라는 창고의 네 단계 용어도 정리해 두세요.'),
('TRK-distribution-H', 'track_competency', '유통 — 강점으로 보여 주기', '유통 채널 구조와 풀필먼트, 가격 구조를 이해하는 점이 강점입니다. 제품 하나의 유통 마진을 단계별로 분석한 자료를 만들어 두면 MD나 유통 직무 면접에서 근거가 됩니다.'),
('TRK-distribution-M', 'track_competency', '유통 — 다음에 더할 것', '채널의 구조는 알고 있습니다. 같은 제품이 온라인과 오프라인에서 어떻게 다른 가격과 마진을 갖는지 비교하고, 반품 처리 같은 역물류 흐름을 한 장으로 그려 보세요.'),
('TRK-distribution-L', 'track_competency', '유통 — 첫걸음', '온라인몰에서 물건을 주문해 도착하기까지의 단계를 풀필먼트 관점에서 주문 처리, 포장, 배송으로 나눠 적어 보세요. 반품할 때 어떤 일이 일어나는지도 정리해 보세요.'),
('TRK-trade_compliance-H', 'track_competency', '무역·통관 — 강점으로 보여 주기', '관세, 인코텀즈, 수출입 서류, FTA를 이해하는 점이 강점입니다. 가상의 수출 거래에서 서류 흐름과 조건별 책임을 정리한 자료를 만들고 관세사나 무역영어 자격 계획을 적어 두세요.'),
('TRK-trade_compliance-M', 'track_competency', '무역·통관 — 다음에 더할 것', '무역 용어는 알고 있습니다. FOB·CIF·EXW 조건별로 운임과 위험을 누가 부담하는지 표로 정리하고 관세청 공개 자료로 FTA 원산지 증명이 무엇인지 읽어 보세요.'),
('TRK-trade_compliance-L', 'track_competency', '무역·통관 — 첫걸음', '인보이스와 선하증권이 각각 어떤 역할인지 한 줄씩 검색해서 정리해 보세요. 관세청의 공개 안내 자료에서 통관이 무엇인지 쉬운 설명을 먼저 읽어 보세요.'),
('TRK-logistics_analytics-H', 'track_competency', '물류 분석 — 강점으로 보여 주기', '데이터로 비용 절감 방안을 낸 경험과 자동화·콜드체인 이해가 강점입니다. 분석 전후 수치와 사용한 도구를 정리해 포트폴리오에 넣고 ERP 재고 모듈 경험도 함께 적으세요.'),
('TRK-logistics_analytics-M', 'track_competency', '물류 분석 — 다음에 더할 것', '분석의 기초는 있습니다. 가상의 배송 데이터로 지역별 비용을 엑셀 피벗으로 비교해 절감 아이디어를 하나 도출하고, 콜드체인에서 온도 관리가 왜 중요한지 사례로 정리해 보세요.'),
('TRK-logistics_analytics-L', 'track_competency', '물류 분석 — 첫걸음', '엑셀로 작은 표를 만들어 월별 물류비의 합계와 평균을 구해 보세요. AGV, 콜드체인이라는 용어가 무엇인지 공개된 물류 기업 소개 자료로 한 번씩 확인해 보세요.'),
('TRK-logistics_leadership-H', 'track_competency', '물류 리더십 — 강점으로 보여 주기', '운영 효율 개선과 현장 소통, 성수기 인력 계획에 강점이 있습니다. 아르바이트나 동아리에서 일이 몰리는 시기를 조율한 경험을 숫자와 함께 정리해 면접에서 이야기해 보세요.'),
('TRK-logistics_leadership-M', 'track_competency', '물류 리더십 — 다음에 더할 것', '현장 운영의 기본은 알고 있습니다. 택배 성수기에 필요한 인력을 가상으로 계산해 보고, 분실이나 파손이 생겼을 때 대응 순서를 단계별 절차로 정리해 보세요.'),
('TRK-logistics_leadership-L', 'track_competency', '물류 리더십 — 첫걸음', '물류센터에서 일하는 사람들의 하루를 다룬 인터뷰나 영상을 찾아보세요. 사고나 지연이 났을 때 고객에게 가장 먼저 무엇을 알려야 할지 생각해 적어 보세요.'),
-- hospitality_food
('TRK-cooking_skill-H', 'track_competency', '조리 — 강점으로 보여 주기', '조리 원리와 식재료 이해, 레시피 표준화에 강점이 있습니다. 직접 개발한 메뉴의 표준 레시피와 시식 평가 결과를 사진과 함께 정리해 포트폴리오로 만들어 보세요.'),
('TRK-cooking_skill-M', 'track_competency', '조리 — 다음에 더할 것', '조리의 기본기는 갖추고 있습니다. 자주 만드는 요리 하나를 계량과 시간까지 적어 표준 레시피로 문서화하고, 다른 사람에게 시식 의견을 받아 기록하는 연습을 더해 보세요.'),
('TRK-cooking_skill-L', 'track_competency', '조리 — 첫걸음', '이번 주에 굽기, 볶기, 찌기 중 한 가지로 간단한 요리를 만들어 보며 불의 세기와 시간을 메모해 보세요. 칼과 불을 쓸 때는 안전 수칙을 지켜 천천히 해 보세요.'),
('TRK-beverage-H', 'track_competency', '음료 — 강점으로 보여 주기', '추출 원리와 주류 지식, 원가 계산에 강점이 있습니다. 바리스타나 소믈리에 같은 관련 자격이나 수료 이력을 명확히 적고 직접 설계한 음료 메뉴의 원가표를 보여 주세요.'),
('TRK-beverage-M', 'track_competency', '음료 — 다음에 더할 것', '음료의 기본 지식은 있습니다. 음료 한 잔의 재료비와 판매가를 계산해 원가율을 구해 보고, 바리스타 자격 과정이나 와인 입문 강좌를 알아보며 전문성 하나를 정해 보세요.'),
('TRK-beverage-L', 'track_competency', '음료 — 첫걸음', '에스프레소와 핸드드립이 추출 방식에서 어떻게 다른지 공개된 입문 영상으로 알아보세요. 카페에서 마신 음료의 맛 차이를 단맛·산미·쓴맛으로 나눠 메모해 보세요.'),
('TRK-food_safety-H', 'track_competency', '위생·식품 안전 — 강점으로 보여 주기', '식품위생법과 HACCP, 교차오염 방지, 알레르기 안내에 강점이 있습니다. 위생교육 수료증과 보건증 같은 증빙을 이력서에 적고 위생 점검표를 직접 만든 경험도 보여 주세요.'),
('TRK-food_safety-M', 'track_competency', '위생·식품 안전 — 다음에 더할 것', '위생의 기본은 지키고 있습니다. 식약처 공개 자료로 HACCP의 7원칙을 정리하고 식재료 보관 온도 기준을 표로 만들어 두면 실무 감각이 확실히 올라갑니다.'),
('TRK-food_safety-L', 'track_competency', '위생·식품 안전 — 첫걸음', '식품의약품안전처의 공개 안내에서 식중독 예방 수칙과 알레르기 유발 식품 목록을 읽어 보세요. 집 냉장고의 보관 온도와 유통기한도 이번 주에 점검해 보세요.'),
('TRK-hospitality_service-H', 'track_competency', '서비스 — 강점으로 보여 주기', '응대의 기본과 불만 대응, 홀 운영, 리뷰 관리를 이해하는 점이 강점입니다. 어려운 손님을 응대해 해결한 사례를 상황·행동·결과로 정리해 면접에서 구체적으로 말해 보세요.'),
('TRK-hospitality_service-M', 'track_competency', '서비스 — 다음에 더할 것', '응대의 기본기는 있습니다. 대기가 길어 불만이 생긴 상황을 가정해 말하는 순서를 대본으로 써 보고, 배달 플랫폼 리뷰에 답글을 다는 연습을 해 보세요.'),
('TRK-hospitality_service-L', 'track_competency', '서비스 — 첫걸음', '이번 주에 방문한 매장에서 인사부터 계산까지 응대가 어땠는지 좋았던 점 두 가지를 적어 보세요. 단기 홀 아르바이트나 체험 행사도 알아볼 만합니다.'),
('TRK-restaurant_ops-H', 'track_competency', '매장 운영 — 강점으로 보여 주기', '원가율과 메뉴 엔지니어링, 발주·재고 관리, POS 분석에 강점이 있습니다. 매출 데이터를 분석해 메뉴를 조정한 경험을 숫자로 정리하고 위생교육 등 인허가 이해도 함께 적어 두세요.'),
('TRK-restaurant_ops-M', 'track_competency', '매장 운영 — 다음에 더할 것', '운영의 기본 개념은 알고 있습니다. 가상의 메뉴 열 가지로 수익성과 인기도를 나눠 4분면으로 분류해 보고, 영업신고와 위생교육 절차를 공개 안내로 확인해 보세요.'),
('TRK-restaurant_ops-L', 'track_competency', '매장 운영 — 첫걸음', '좋아하는 메뉴 하나의 재료비를 대략 추정하고 판매가로 나눠 원가율을 계산해 보세요. 식당 영업에 필요한 허가가 무엇인지 지자체 안내를 한 번 찾아보세요.'),
('TRK-fb_business-H', 'track_competency', 'F&B 사업 — 강점으로 보여 주기', '외식 트렌드와 손익분기점 분석, 디지털 전환을 이해하는 점이 강점입니다. 가상의 매장으로 손익분기 계산과 상권 분석을 담은 간단한 사업 계획서를 만들어 포트폴리오에 넣어 보세요.'),
('TRK-fb_business-M', 'track_competency', 'F&B 사업 — 다음에 더할 것', '트렌드를 보는 눈은 있습니다. 프랜차이즈와 개인 매장의 장단점을 표로 비교하고, 고정비와 변동비로 손익분기 매출을 직접 계산해 보면 사업 감각이 단단해집니다.'),
('TRK-fb_business-L', 'track_competency', 'F&B 사업 — 첫걸음', '요즘 눈에 띄는 외식 트렌드 한 가지를 골라 매장 두 곳을 직접 방문해 비교해 보세요. 키오스크나 서빙 로봇을 쓰는 매장의 이유도 생각해 적어 보세요.'),
-- medical_health
('TRK-clinical_knowledge-H', 'track_competency', '임상 지식 — 강점으로 보여 주기', '기관계와 질환 경로, 의학 용어, 근거 기반 의학을 이해하는 점이 강점입니다. 관심 질환의 최신 가이드라인을 요약한 노트나 논문 읽기 기록을 정리해 학업 역량의 증거로 보여 주세요.'),
('TRK-clinical_knowledge-M', 'track_competency', '임상 지식 — 다음에 더할 것', '기본 지식은 있습니다. 관심 질환 하나를 골라 대한의학회나 보건 당국의 공개 가이드라인을 읽고, 증상에서 진단과 치료까지 경로를 한 장으로 정리하는 연습을 더해 보세요.'),
('TRK-clinical_knowledge-L', 'track_competency', '임상 지식 — 첫걸음', '순환계나 호흡계 중 한 가지를 정해 공개 강의로 구조와 기능을 공부하고, 의학 용어 열 개를 영문과 함께 정리해 보세요. 지식을 환자에게 직접 적용하지는 마세요.'),
('TRK-patient_care-H', 'track_competency', '환자 케어 — 강점으로 보여 주기', '공감하는 소통과 관찰·기록, 감염 관리 원칙을 이해하는 점이 강점입니다. 대한적십자사 응급처치나 BLS 교육 이수증을 이력서에 적고 봉사 활동에서 배려했던 사례를 정리하세요.'),
('TRK-patient_care-M', 'track_competency', '환자 케어 — 다음에 더할 것', '케어의 기본 태도는 있습니다. 공인 기관의 BLS 교육 과정을 알아보고, 손위생 6단계와 낙상 예방 수칙을 공개 자료로 익혀 실제 상황에서 지킬 수 있게 준비하세요.'),
('TRK-patient_care-L', 'track_competency', '환자 케어 — 첫걸음', '보건복지부나 질병관리청의 공개 자료로 손위생 방법을 먼저 익혀 보세요. 응급 처치는 공인 교육을 받은 뒤에만 하고, 병원 봉사는 기관이 정한 범위에서 시작하세요.'),
('TRK-medical_teamwork-H', 'track_competency', '의료 협업 — 강점으로 보여 주기', '다직종 협업의 중요성과 교대 근무 수용, 자기 관리 방법을 아는 점이 강점입니다. 팀 활동에서 역할을 나누고 갈등을 풀었던 경험을 정리하고 보수교육에 대한 학습 계획도 밝히세요.'),
('TRK-medical_teamwork-M', 'track_competency', '의료 협업 — 다음에 더할 것', '협업의 가치는 이해하고 있습니다. 의사·간호사·약사의 역할이 환자 한 명에게 어떻게 이어지는지 공개 사례로 정리하고, 번아웃 예방 방법을 내 생활에 적용해 보세요.'),
('TRK-medical_teamwork-L', 'track_competency', '의료 협업 — 첫걸음', '현직 의료인의 하루를 다룬 인터뷰나 다큐를 찾아보며 교대 근무와 당직이 어떤 생활인지 느껴 보세요. 나에게 맞을지 생각해 메모로 남겨 보세요.'),
('TRK-medical_ethics-H', 'track_competency', '의료 윤리 — 강점으로 보여 주기', '의료윤리 4대 원칙과 개인정보 보호, 동의 원칙을 아는 점이 강점입니다. 윤리 사례를 4대 원칙에 맞춰 분석한 글을 작성해 두고 면접에서 판단 과정을 설명해 보세요.'),
('TRK-medical_ethics-M', 'track_competency', '의료 윤리 — 다음에 더할 것', '원칙은 이해하고 있습니다. 의료법과 개인정보보호법에서 환자 정보를 다루는 조항을 국가법령정보센터에서 찾아 읽고, 인폼드 컨센트가 부족했던 사례를 하나 분석해 보세요.'),
('TRK-medical_ethics-L', 'track_competency', '의료 윤리 — 첫걸음', '자율성, 선행, 악행금지, 정의라는 네 원칙을 일상의 예시로 한 줄씩 풀어 적어 보세요. 환자의 개인정보를 왜 함부로 말하면 안 되는지도 생각해 보세요.'),
('TRK-health_admin-H', 'track_competency', '보건 행정 — 강점으로 보여 주기', '건강보험 체계와 병원 조직, EMR, 의료기관 인증을 이해하는 점이 강점입니다. 건강보험 급여 구조를 그림으로 설명한 자료를 만들어 두면 병원 행정이나 보건 직무 면접에서 쓸모가 큽니다.'),
('TRK-health_admin-M', 'track_competency', '보건 행정 — 다음에 더할 것', '행정의 기본 구조는 알고 있습니다. 급여와 비급여의 차이를 건강보험공단의 공개 자료로 사례와 함께 정리하고, 의료기관 인증 평가가 어떤 항목을 보는지 개요를 읽어 보세요.'),
('TRK-health_admin-L', 'track_competency', '보건 행정 — 첫걸음', '건강보험공단의 쉬운 안내 자료로 건강보험이 무엇인지 읽어 보세요. 병원의 진료과와 행정부서가 각각 무슨 일을 하는지 병원 홈페이지의 조직도로 확인해 보세요.'),
('TRK-digital_health-H', 'track_competency', '디지털 헬스 — 강점으로 보여 주기', '원격의료와 의료 AI의 가능성과 한계를 함께 아는 점이 강점입니다. 디지털 헬스 사례를 비판적으로 분석한 짧은 글이나 발표 자료를 만들어 의료 정보 직무의 증거로 활용하세요.'),
('TRK-digital_health-M', 'track_competency', '디지털 헬스 — 다음에 더할 것', '트렌드는 알고 있습니다. 웨어러블이나 의료 AI 사례 하나를 골라 어떤 데이터를 쓰는지, 한계와 개인정보 문제가 무엇인지 두 가지씩 정리해 보세요.'),
('TRK-digital_health-L', 'track_competency', '디지털 헬스 — 첫걸음', '원격의료나 웨어러블 기기 중 관심 있는 것 하나의 기사를 읽고 장점과 걱정되는 점을 한 줄씩 적어 보세요. 신약 개발이 어떤 단계를 거치는지도 알아보세요.')
ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, title = EXCLUDED.title, content = EXCLUDED.content;
